import io,tokenize,os,collections
strs=[]
for dp,dn,fn in os.walk('.'):
    dn[:]=[d for d in dn if d not in ('.git','__pycache__')]
    for f in fn:
        p=os.path.join(dp,f)
        if not (p.endswith('.py')): continue
        if any(p.startswith('./'+x) for x in ('logs/','third_party/','legacy_cache/')): continue
        try: toks=list(tokenize.generate_tokens(io.StringIO(open(p,encoding='utf-8',errors='replace').read()).readline))
        except Exception as e: print('ERR',p,e); continue
        for t in toks:
            if t.type==tokenize.STRING and 'fetch_user' in t.string:
                strs.append((p,t.start[0],t.string))
print(len(strs))
