import io, os, re, tokenize

SKIP_PREFIXES = ('logs/', 'third_party/', 'legacy_cache/')
SKIP_FILES = {'harbor/accounts/__init__.py'}
GENERATED = re.compile(r'^harbor/proto/.*_pb2\.py$')

def offsets(src):
    lines = src.splitlines(keepends=True)
    starts=[]; pos=0
    for ln in lines:
        starts.append(pos); pos += len(ln)
    return starts

def apply_edits(src, edits):
    starts=offsets(src)
    for (srow,scol),(erow,ecol),new in sorted(edits, reverse=True):
        s=starts[srow-1]+scol; e=starts[erow-1]+ecol
        src=src[:s]+new+src[e:]
    return src

def rewrite(path):
    src=open(path,encoding='utf-8').read()
    try: toks=list(tokenize.generate_tokens(io.StringIO(src).readline))
    except Exception as e:
        return None, f'tokenize error: {e}'
    edits=[]
    for idx,t in enumerate(toks):
        if t.type==tokenize.NAME and t.string=='fetch_user':
            prev = toks[idx-1].string if idx else ''
            prev2 = toks[idx-2].string if idx>=2 else ''
            if prev=='.' and prev2 not in ('accounts','acct'):
                continue
            edits.append((t.start,t.end,'load_account'))
        elif t.type==tokenize.STRING:
            s=t.string
            m=re.fullmatch(r'([A-Za-z]*)("""|\'\'\'|"|\')(.*)\2', s, re.S)
            if not m: continue
            prefix, quote, body = m.groups()
            if 'fetch_user' not in body: continue
            newbody=body
            if body=='harbor.accounts:fetch_user':
                newbody='harbor.accounts:load_account'
            elif body=='fetch_user':
                newbody='load_account'
            else:
                dm=re.fullmatch(r'(harbor\.[\w.]+)\.fetch_user', body)
                if dm and not (body.startswith('harbor.integrations.github.') or body.startswith('harbor.admin.shell.')):
                    newbody=body[:-len('fetch_user')]+'load_account'
            if newbody!=body:
                edits.append((t.start,t.end,prefix+quote+newbody+quote))
    if not edits: return src, 0
    return apply_edits(src,edits), len(edits)

changed=[]
count=0
for dp,dn,fn in os.walk('.'):
    dn[:]=[d for d in dn if d not in ('.git','__pycache__')]
    for f in fn:
        p=os.path.join(dp,f)
        rel=p[2:] if p.startswith('./') else p
        if not rel.endswith('.py'): continue
        if rel in SKIP_FILES or GENERATED.match(rel): continue
        if any(rel.startswith(x) for x in SKIP_PREFIXES): continue
        new,n=rewrite(p)
        if new is not None and n:
            open(p,'w',encoding='utf-8').write(new)
            changed.append((rel,n)); count+=n
print('changed files',len(changed),'edits',count)
for rel,n in changed[:15]: print(n,rel)

