    lines=src.splitlines(keepends=True); starts=[]; pos=0
    for ln in lines: starts.append(pos); pos+=len(ln)
    return starts
def apply_edits(src,edits):
    starts=offsets(src)
    for (sr,sc),(er,ec),new in sorted(edits,reverse=True):
        s=starts[sr-1]+sc; e=starts[er-1]+ec; src=src[:s]+new+src[e:]
    return src
def rewrite(path):
    src=open(path,encoding='utf-8').read()
    toks=list(tokenize.generate_tokens(io.StringIO(src).readline))
