import io, os, re, tokenize
bad=[]
for dp,dn,fn in os.walk('.'):
    dn[:]=[d for d in dn if d not in ('.git','__pycache__')]
    for f in fn:
        p=os.path.join(dp,f)
        rel=p[2:] if p.startswith('./') else p
        if any(rel.startswith(x) for x in ('logs/','third_party/','legacy_cache/')): continue
        if not rel.endswith('.py'): continue
        try:
            src=open(p,encoding='utf-8',errors='replace').read()
            toks=list(tokenize.generate_tokens(io.StringIO(src).readline))
        except Exception as e:
            bad.append((rel,'tokenize',str(e))); continue
        for t in toks:
            if t.type==tokenize.NAME and t.string=='fetch_user':
                prev=toks[toks.index(t)-1].string if toks.index(t)>0 else ''
                prev2=toks[toks.index(t)-2].string if toks.index(t)>=2 else ''
                allowed = (prev=='.' and prev2 not in ('accounts','acct')) or rel in ('harbor/accounts/__init__.py','harbor/admin/shell.py','harbor/integrations/github.py','harbor/integrations/sync.py','tests/test_integrations.py')
                if not allowed: bad.append((rel,t.start[0],t.string))
            if t.type==tokenize.STRING and 'fetch_user' in t.string:
                body=t.string.strip('"\'')
                allowed = (body.startswith('accounts.fetch_user.') or 'fetch_user returned nothing' in body or body=='fetch_user is deprecated, use load_account (removal in 4.0)' or body in ('fetch_user_count','harbor.accounts:fetch_user_count','harbor.integrations.github:GitHubClient.fetch_user'))
                if not allowed: bad.append((rel,t.start[0],t.string))
print('unexpected remaining fetch_user refs:',bad)
ns={}
exec('from harbor.accounts import *', ns)
assert 'load_account' in ns and 'fetch_user' not in ns
print('star-import check ok')
